DECLARE packs jsonb := $pack$[{"codigo":"S22R-C01","legacy_id":459,"legacy_ids":[459],"relacionadas":["S15-C05"],"residual":"","coberturas":[{"legacy_id":459,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"En onboarding Cliente BLOQUEAR instrumentación de funnel que omita HOME_CTA, PHONE_SUBMITTED, OTP_VERIFIED, DNI_SUBMITTED, MATCH_RESULT, OFFER_INTEREST, OFFER_VIEW o EXIT cuando correspondan, o exponga PII cruda en analytics. Medir señales agregadas DISTINCT_DNI_PER_ORIGIN, DISTINCT_PHONE_PER_ORIGIN, REPEATED_QUERIES, RATE_LIMIT_HITS, SYSTEMATIC_MATCH_EXIT, DISTINCT_DNI_PER_VERIFIED_PHONE y DISTINCT_RECOVERY_ACCOUNTS_PER_VERIFIED_PHONE para distinguir rechazo de oferta de exploración automatizada/competencia. Outputs NORMAL/SUSPECT/HIGH, thresholds PENDING_BASELINE sin inventar límites ni activar IDV. Conservar referencias REG_RISK_PHONE_MULTI_DNI_001 y REG_IDV_PROGRESSIVE_001, decisión 71. Complementa S15-C05; binding pendiente."}],"hechos":["s22r01_evalua_telemetria_onb","s22r01_evento_falta","s22r01_senal_agregada_falta","s22r01_pii_cruda","s22r01_riesgo_o_umbral_inventado"],"paquete":{"tipo":"NUEVA","codigo":"S22R-C01","clave":"s22r_legacy_459","familia":"ANALYTICS","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_ONBOARDING","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Telemetría de funnel y señales de abuso sin PII cruda","descripcion":"En onboarding Cliente BLOQUEAR instrumentación de funnel que omita HOME_CTA, PHONE_SUBMITTED, OTP_VERIFIED, DNI_SUBMITTED, MATCH_RESULT, OFFER_INTEREST, OFFER_VIEW o EXIT cuando correspondan, o exponga PII cruda en analytics. Medir señales agregadas DISTINCT_DNI_PER_ORIGIN, DISTINCT_PHONE_PER_ORIGIN, REPEATED_QUERIES, RATE_LIMIT_HITS, SYSTEMATIC_MATCH_EXIT, DISTINCT_DNI_PER_VERIFIED_PHONE y DISTINCT_RECOVERY_ACCOUNTS_PER_VERIFIED_PHONE para distinguir rechazo de oferta de exploración automatizada/competencia. Outputs NORMAL/SUSPECT/HIGH, thresholds PENDING_BASELINE sin inventar límites ni activar IDV