on_sin_flag_server":false,"s22r07_claim_sin_evidencia":true,"s22r07_no_preserva_operacion_o_seleccion":false,"s22r07_plan_activo_sin_confirmacion":false,"s22r07_branding_sin_binding":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22r07_evalua_error_pago":true,"s22r07_outcome_no_permitido":false,"s22r07_accion_sin_flag_server":false,"s22r07_claim_sin_evidencia":false,"s22r07_no_preserva_operacion_o_seleccion":true,"s22r07_plan_activo_sin_confirmacion":false,"s22r07_branding_sin_binding":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22r07_evalua_error_pago":true,"s22r07_outcome_no_permitido":false,"s22r07_accion_sin_flag_server":false,"s22r07_claim_sin_evidencia":false,"s22r07_no_preserva_operacion_o_seleccion":false,"s22r07_plan_activo_sin_confirmacion":true,"s22r07_branding_sin_binding":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22r07_evalua_error_pago":true,"s22r07_outcome_no_permitido":false,"s22r07_accion_sin_flag_server":false,"s22r07_claim_sin_evidencia":false,"s22r07_no_preserva_operacion_o_seleccion":false,"s22r07_plan_activo_sin_confirmacion":false,"s22r07_branding_sin_binding":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22r07_evalua_error_pago":false,"s22r07_outcome_no_permitido":true,"s22r07_accion_sin_flag_server":true,"s22r07_claim_sin_evidencia":true,"s22r07_no_preserva_operacion_o_seleccion":true,"s22r07_plan_activo_sin_confirmacion":true,"s22r07_branding_sin_binding":true},"esperado":false}]},"hash":"548b3ce13bc2dacc64147a02fc33b2811a6123758e28f04a6b95f154fc8a6f63","hash_paquete":"f0559c1cb22c6a1c70c2adc16e3c7a7db206cc6712d0b43e1da0bd206f642609","hash_evaluado":"548b3ce13b","hash_paquete_10":"f0559c1cb2"}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 n:=n+1;
 END LOOP;
 IF n<>7 OR vectors<>51 THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S22R proposal-only: independent judgment pending';
END $s22$;
COMMIT;
